// WebGL2 fragment-shader ray tracer. No rasterized geometry: every pixel
// casts a primary ray against the analytic scene (AABBs + spheres), then
// shadow rays, AO rays, and reflection bounces per settings.
// Map geometry, lights, and theme are uploaded at runtime via loadMap().

const MAX_BOXES = 64;
const MAX_SPHERES = 48;
const NUM_LIGHTS = 12;
const MAX_BOUNCES = 3;

const VERT = `#version 300 es
layout(location=0) in vec2 aPos;
void main(){ gl_Position = vec4(aPos, 0.0, 1.0); }
`;

const FRAG = `#version 300 es
precision highp float;
precision highp int;
precision highp sampler2D;

#define MAX_BOXES ${MAX_BOXES}
#define MAX_SPHERES ${MAX_SPHERES}
#define NUM_LIGHTS ${NUM_LIGHTS}
#define MAX_BOUNCES ${MAX_BOUNCES}

out vec4 outColor;

uniform vec2 uRes;
uniform float uTime;
uniform vec3 uCamPos;
uniform vec3 uCamFwd;
uniform vec3 uCamRight;
uniform vec3 uCamUp;
uniform float uTanY;

uniform sampler2D uBoxTex;       // row 0: (min.xyz, mat), row 1: (max.xyz, 0)
uniform int uNumBoxes;
uniform vec4 uSpheres[MAX_SPHERES]; // xyz center, w radius
uniform vec4 uSphereMat[MAX_SPHERES]; // x: material id, yzw: tint color
uniform int uNumSpheres;

uniform vec3 uSunDir;
uniform vec3 uSunCol;
uniform float uSunInt;
uniform vec4 uLightPos[NUM_LIGHTS]; // xyz, w intensity
uniform vec3 uLightCol[NUM_LIGHTS];

// theme
uniform vec3 uSkyTop;
uniform vec3 uSkyHorizon;
uniform vec3 uHaze;
uniform vec3 uFogCol;
uniform vec3 uNeonA;
uniform vec3 uNeonB;

uniform int uBounces;       // 0..3
uniform int uShadowMode;    // 0 off, 1 hard, 2 soft
uniform int uShadowSamples; // soft shadow samples
uniform int uAOMode;        // 0 off, 1 low (2 rays), 2 high (4 rays)
uniform int uFog;
uniform int uPulse;
uniform int uDebugMat;      // >=0: render material swatch fullscreen

// ---------- hash / noise ----------
float hash12(vec2 p){
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float hash13(vec3 p){
  p = fract(p * vec3(123.34, 456.21, 789.92));
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}
float vnoise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash12(i);
  float b = hash12(i + vec2(1.0, 0.0));
  float c = hash12(i + vec2(0.0, 1.0));
  float d = hash12(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p){
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 3; i++){
    v += a * vnoise(p);
    p = p * 2.13 + vec2(7.7);
    a *= 0.5;
  }
  return v;
}

// ---------- intersections ----------
float iBox(vec3 ro, vec3 rd, vec3 bmin, vec3 bmax, out vec3 n){
  vec3 inv = 1.0 / rd;
  vec3 t0 = (bmin - ro) * inv;
  vec3 t1 = (bmax - ro) * inv;
  vec3 tsm = min(t0, t1);
  vec3 tbg = max(t0, t1);
  float tN = max(max(tsm.x, tsm.y), tsm.z);
  float tF = min(min(tbg.x, tbg.y), tbg.z);
  if (tN > tF || tF < 0.0) { n = vec3(0.0); return -1.0; }
  float t = tN >= 0.0 ? tN : tF;
  vec3 axis = step(vec3(tN - 1e-4), tsm);
  n = -sign(rd) * axis;
  if (tN < 0.0) n = -n;
  return t;
}
float iSphere(vec3 ro, vec3 rd, vec3 c, float r){
  vec3 oc = ro - c;
  float b = dot(oc, rd);
  float cc = dot(oc, oc) - r * r;
  float h = b * b - cc;
  if (h < 0.0) return -1.0;
  float t = -b - sqrt(h);
  return t > 0.0 ? t : -1.0;
}

struct Hit { float t; vec3 n; float mat; vec3 p; int sph; };

bool trace(vec3 ro, vec3 rd, float maxT, out Hit h){
  h.t = maxT;
  h.mat = -1.0;
  h.n = vec3(0.0, 1.0, 0.0);
  h.sph = -1;
  for (int i = 0; i < MAX_BOXES; i++){
    if (i >= uNumBoxes) break;
    vec4 a = texelFetch(uBoxTex, ivec2(i, 0), 0);
    vec4 b = texelFetch(uBoxTex, ivec2(i, 1), 0);
    vec3 n;
    float t = iBox(ro, rd, a.xyz, b.xyz, n);
    if (t > 0.001 && t < h.t){ h.t = t; h.n = n; h.mat = a.w; }
  }
  for (int i = 0; i < MAX_SPHERES; i++){
    if (i >= uNumSpheres) break;
    float t = iSphere(ro, rd, uSpheres[i].xyz, uSpheres[i].w);
    if (t > 0.001 && t < h.t){
      h.t = t;
      h.n = normalize(ro + rd * t - uSpheres[i].xyz);
      h.mat = uSphereMat[i].x;
      h.sph = i;
    }
  }
  if (h.mat < 0.0) return false;
  h.p = ro + rd * h.t;
  return true;
}

bool anyHit(vec3 ro, vec3 rd, float maxT){
  for (int i = 0; i < MAX_BOXES; i++){
    if (i >= uNumBoxes) break;
    vec4 a = texelFetch(uBoxTex, ivec2(i, 0), 0);
    vec4 b = texelFetch(uBoxTex, ivec2(i, 1), 0);
    vec3 n;
    float t = iBox(ro, rd, a.xyz, b.xyz, n);
    if (t > 0.001 && t < maxT) return true;
  }
  for (int i = 0; i < MAX_SPHERES; i++){
    if (i >= uNumSpheres) break;
    float t = iSphere(ro, rd, uSpheres[i].xyz, uSpheres[i].w);
    if (t > 0.001 && t < maxT) return true;
  }
  return false;
}

// ---------- materials ----------
vec2 triUV(vec3 p, vec3 n){
  vec3 an = abs(n);
  if (an.y >= an.x && an.y >= an.z) return p.xz;
  if (an.x >= an.z) return p.zy;
  return p.xy;
}

struct Mat { vec3 albedo; float refl; vec3 emissive; float spec; };

Mat getMat(float matId, vec3 p, vec3 n){
  Mat m;
  m.refl = 0.0;
  m.emissive = vec3(0.0);
  m.spec = 8.0;
  vec2 uv = triUV(p, n);
  int id = int(matId + 0.5);

  if (id == 0){ // asphalt floor: speckle + faint painted grid
    float sp = fbm(uv * 3.0);
    m.albedo = vec3(0.11, 0.115, 0.135) * (0.7 + 0.6 * sp);
    vec2 g = abs(fract(uv * 0.125) - 0.5);
    float line = smoothstep(0.485, 0.5, max(g.x, g.y));
    m.albedo += uNeonA * 0.12 * line;
    m.refl = 0.09;
    m.spec = 24.0;
  } else if (id == 1){ // brick
    vec2 b = uv * vec2(1.0, 2.0);
    float row = floor(b.y);
    b.x += row * 0.5;
    vec2 f = fract(b);
    float mortar = step(f.x, 0.06) + step(0.94, f.x) + step(f.y, 0.12) + step(0.88, f.y);
    mortar = clamp(mortar, 0.0, 1.0);
    float tint = 0.75 + 0.5 * hash12(floor(b));
    vec3 brick = vec3(0.42, 0.16, 0.12) * tint * (0.85 + 0.3 * fbm(uv * 6.0));
    m.albedo = mix(brick, vec3(0.32, 0.3, 0.28), mortar);
  } else if (id == 2){ // wood crate: planks + edge banding
    float plank = floor(uv.y * 3.0);
    float grain = fbm(vec2(uv.x * 8.0, uv.y * 1.5 + plank * 13.7));
    vec3 wood = vec3(0.45, 0.3, 0.15) * (0.65 + 0.55 * grain) * (0.85 + 0.3 * hash12(vec2(plank, 1.0)));
    vec2 e = abs(fract(uv * 0.5) - 0.5);
    float band = smoothstep(0.43, 0.46, max(e.x, e.y));
    m.albedo = mix(wood, vec3(0.25, 0.18, 0.1), band * 0.8);
    float gap = smoothstep(0.92, 0.98, fract(uv.y * 3.0));
    m.albedo *= 1.0 - 0.5 * gap;
  } else if (id == 3){ // brushed metal panels
    float brush = vnoise(vec2(uv.x * 40.0, uv.y * 2.0));
    vec2 pf = abs(fract(uv * 0.5) - 0.5);
    float seam = smoothstep(0.46, 0.49, max(pf.x, pf.y));
    m.albedo = vec3(0.5, 0.54, 0.6) * (0.7 + 0.3 * brush) * (1.0 - 0.55 * seam);
    m.refl = 0.42;
    m.spec = 64.0;
  } else if (id == 4 || id == 5){ // neon strips (theme-tinted)
    vec3 col = id == 4 ? uNeonA : uNeonB;
    float pulse = uPulse == 1 ? 0.78 + 0.22 * sin(uTime * 2.4 + p.x * 0.21 + p.z * 0.17) : 1.0;
    m.albedo = col * 0.08;
    m.emissive = col * 2.2 * pulse;
  } else if (id == 6){ // dark metal panel
    vec2 pf = abs(fract(uv * 0.7) - 0.5);
    float seam = smoothstep(0.45, 0.48, max(pf.x, pf.y));
    m.albedo = vec3(0.12, 0.13, 0.16) * (0.8 + 0.4 * fbm(uv * 4.0)) * (1.0 - 0.5 * seam);
    m.refl = 0.24;
    m.spec = 48.0;
  } else if (id == 7){ // plaster: pale, stained
    float stain = fbm(uv * 1.7);
    m.albedo = vec3(0.55, 0.53, 0.48) * (0.72 + 0.35 * stain);
    float drip = fbm(vec2(uv.x * 9.0, uv.y * 0.6));
    m.albedo *= 1.0 - 0.25 * smoothstep(0.55, 0.8, drip);
  } else if (id == 8){ // character chassis (tinted per-sphere)
    float panel = vnoise(uv * 6.0);
    m.albedo = vec3(0.55) * (0.8 + 0.4 * panel);
    m.refl = 0.16;
    m.spec = 32.0;
  } else if (id == 9){ // character visor: emissive (tinted per-sphere)
    m.albedo = vec3(0.08);
    m.emissive = vec3(3.2);
    m.refl = 0.1;
  } else if (id == 10){ // hazard crate: orange + black chevrons
    float stripe = step(0.5, fract((uv.x + uv.y) * 1.2));
    vec3 orange = vec3(0.85, 0.4, 0.05) * (0.8 + 0.3 * fbm(uv * 5.0));
    m.albedo = mix(orange, vec3(0.1, 0.1, 0.1), stripe * 0.85);
  } else if (id == 11){ // character cloth (tinted): matte weave
    float weave = vnoise(uv * 18.0);
    m.albedo = vec3(0.5) * (0.75 + 0.3 * weave);
    m.spec = 6.0;
  } else {
    m.albedo = vec3(1.0, 0.0, 1.0);
  }
  return m;
}

// ---------- sky ----------
vec3 sky(vec3 rd){
  float h = clamp(rd.y, 0.0, 1.0);
  vec3 base = mix(uSkyHorizon, uSkyTop, pow(h, 0.6));
  float hz = exp(-abs(rd.y) * 9.0);
  base += uHaze * hz;
  base += uHaze.zxy * 0.5 * hz * (0.5 + 0.5 * sin(atan(rd.z, rd.x) * 2.0));
  vec3 sd = floor(rd * 220.0);
  float st = step(0.998, hash13(sd)) * smoothstep(0.05, 0.3, rd.y);
  base += vec3(st) * 0.6;
  float moon = smoothstep(0.9985, 0.999, dot(rd, -uSunDir));
  base += uSunCol * moon * 2.5;
  return base;
}

// ---------- lighting ----------
vec3 jitterDir(vec3 d, float spread, vec3 seed){
  vec3 r = vec3(hash13(seed), hash13(seed + 17.1), hash13(seed + 41.7)) - 0.5;
  return normalize(d + r * spread);
}

float sunShadow(vec3 p, vec3 n){
  if (uShadowMode == 0) return 1.0;
  vec3 ro = p + n * 0.01;
  vec3 sd = -uSunDir;
  if (uShadowMode == 1){
    return anyHit(ro, sd, 100.0) ? 0.0 : 1.0;
  }
  float acc = 0.0;
  for (int s = 0; s < 8; s++){
    if (s >= uShadowSamples) break;
    vec3 d = jitterDir(sd, 0.04, p * 13.7 + float(s));
    acc += anyHit(ro, d, 100.0) ? 0.0 : 1.0;
  }
  return acc / float(uShadowSamples);
}

float ambOcc(vec3 p, vec3 n){
  if (uAOMode == 0) return 1.0;
  int rays = uAOMode == 1 ? 2 : 4;
  float acc = 0.0;
  for (int s = 0; s < 4; s++){
    if (s >= rays) break;
    vec3 d = jitterDir(n, 1.4, p * 7.3 + float(s) * 3.1);
    if (dot(d, n) < 0.0) d = reflect(d, n);
    acc += anyHit(p + n * 0.02, d, 1.8) ? 0.0 : 1.0;
  }
  return 0.35 + 0.65 * (acc / float(rays));
}

vec3 shade(vec3 p, vec3 n, vec3 rd, Mat m){
  vec3 col = m.emissive;
  float ao = ambOcc(p, n);
  vec3 amb = mix(uSkyHorizon * 0.6 + vec3(0.02), uSkyTop * 1.4 + uSkyHorizon * 0.35, n.y * 0.5 + 0.5);
  col += m.albedo * amb * ao;
  float ndl = max(dot(n, -uSunDir), 0.0);
  if (ndl > 0.0){
    float sh = sunShadow(p, n);
    col += m.albedo * uSunCol * (ndl * uSunInt * sh);
    vec3 hv = normalize(-uSunDir - rd);
    col += uSunCol * pow(max(dot(n, hv), 0.0), m.spec) * 0.25 * sh;
  }
  for (int i = 0; i < NUM_LIGHTS; i++){
    float inten = uLightPos[i].w;
    if (inten <= 0.001) continue;
    vec3 lv = uLightPos[i].xyz - p;
    float d2 = dot(lv, lv);
    float d = sqrt(d2);
    vec3 ld = lv / d;
    float ndl2 = max(dot(n, ld), 0.0);
    if (ndl2 <= 0.0) continue;
    float att = inten / (1.0 + d2 * 0.55);
    col += m.albedo * uLightCol[i] * (ndl2 * att);
    vec3 hv = normalize(ld - rd);
    col += uLightCol[i] * pow(max(dot(n, hv), 0.0), m.spec) * att * 0.3;
  }
  return col;
}

vec3 render(vec3 ro, vec3 rd){
  vec3 col = vec3(0.0);
  vec3 thr = vec3(1.0);
  float firstT = -1.0;
  for (int bounce = 0; bounce <= MAX_BOUNCES; bounce++){
    if (bounce > uBounces) break;
    Hit h;
    if (!trace(ro, rd, 300.0, h)){
      col += thr * sky(rd);
      break;
    }
    if (bounce == 0) firstT = h.t;
    Mat m = getMat(h.mat, h.p, h.n);
    if (h.sph >= 0){
      vec3 tint = uSphereMat[h.sph].yzw;
      m.albedo *= tint;
      m.emissive *= tint;
    }
    vec3 local = shade(h.p, h.n, rd, m);
    col += thr * local;
    float fres = m.refl + (1.0 - m.refl) * pow(1.0 - max(dot(-rd, h.n), 0.0), 5.0) * m.refl * 0.4;
    if (fres < 0.02) break;
    thr *= fres;
    if (max(thr.x, max(thr.y, thr.z)) < 0.015) break;
    rd = reflect(rd, h.n);
    ro = h.p + h.n * 0.01;
  }
  if (uFog == 1 && firstT > 0.0){
    float f = 1.0 - exp(-firstT * 0.013);
    col = mix(col, uFogCol, f * 0.85);
  }
  return col;
}

vec3 aces(vec3 x){
  return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

void main(){
  if (uDebugMat >= 0){
    vec2 uv = gl_FragCoord.xy / uRes;
    vec3 p = vec3(uv.x * 8.0, 0.0, uv.y * 8.0);
    Mat m = getMat(float(uDebugMat), p, vec3(0.0, 1.0, 0.0));
    vec3 c = m.albedo * 0.9 + m.emissive * 0.5;
    outColor = vec4(pow(aces(c), vec3(1.0 / 2.2)), 1.0);
    return;
  }
  vec2 ndc = (gl_FragCoord.xy / uRes) * 2.0 - 1.0;
  float aspect = uRes.x / uRes.y;
  vec3 rd = normalize(uCamFwd + uCamRight * ndc.x * uTanY * aspect + uCamUp * ndc.y * uTanY);
  vec3 col = render(uCamPos, rd);
  col = aces(col);
  float vig = 1.0 - 0.25 * dot(ndc * 0.7, ndc * 0.7);
  col *= vig;
  outColor = vec4(pow(col, vec3(1.0 / 2.2)), 1.0);
}
`;

export const MATERIAL_NAMES = [
  'asphalt floor', 'brick wall', 'wood crate', 'brushed metal',
  'neon strip A', 'neon strip B', 'dark metal panel',
  'plaster wall', 'char chassis', 'char visor', 'hazard crate', 'char cloth',
];

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    const gl = canvas.getContext('webgl2', { antialias: false, powerPreference: 'high-performance' });
    if (!gl) throw new Error('WebGL2 unavailable — NEONSTRIKE needs WebGL2 for ray tracing');
    this.gl = gl;
    this.program = this._compile(VERT, FRAG);
    this.uni = {};
    const names = [
      'uRes', 'uTime', 'uCamPos', 'uCamFwd', 'uCamRight', 'uCamUp', 'uTanY',
      'uBoxTex', 'uNumBoxes', 'uSpheres', 'uSphereMat', 'uNumSpheres',
      'uSunDir', 'uSunCol', 'uSunInt', 'uLightPos', 'uLightCol',
      'uSkyTop', 'uSkyHorizon', 'uHaze', 'uFogCol', 'uNeonA', 'uNeonB',
      'uBounces', 'uShadowMode', 'uShadowSamples', 'uAOMode', 'uFog', 'uPulse', 'uDebugMat',
    ];
    for (const n of names) this.uni[n] = gl.getUniformLocation(this.program, n);

    const vao = gl.createVertexArray();
    gl.bindVertexArray(vao);
    const vb = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, vb);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    this.vao = vao;

    this.boxTex = gl.createTexture();
    this.numBoxes = 0;
    this.sphereData = new Float32Array(MAX_SPHERES * 4);
    this.sphereMats = new Float32Array(MAX_SPHERES * 4);
    this.numSpheres = 0;
    this.lightPos = new Float32Array(NUM_LIGHTS * 4);
    this.lightCol = new Float32Array(NUM_LIGHTS * 3);
    this.muzzleIndex = 0;
    this.theme = null;
    this.sunDir = [0, -1, 0];
    this.sunCol = [1, 1, 1];
    this.sunInt = 1;
    this.debugMat = -1;
  }

  _compile(vsSrc, fsSrc) {
    const gl = this.gl;
    const mk = (type, src) => {
      const s = gl.createShader(type);
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
        throw new Error('Shader compile failed: ' + gl.getShaderInfoLog(s));
      }
      return s;
    };
    const p = gl.createProgram();
    gl.attachShader(p, mk(gl.VERTEX_SHADER, vsSrc));
    gl.attachShader(p, mk(gl.FRAGMENT_SHADER, fsSrc));
    gl.linkProgram(p);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) {
      throw new Error('Program link failed: ' + gl.getProgramInfoLog(p));
    }
    return p;
  }

  loadMap(map) {
    const gl = this.gl;
    const n = Math.min(map.BOXES.length, MAX_BOXES);
    this.numBoxes = n;
    const data = new Float32Array(MAX_BOXES * 2 * 4);
    for (let i = 0; i < n; i++) {
      const b = map.BOXES[i];
      data.set([b[0], b[1], b[2], b[6]], i * 4);
      data.set([b[3], b[4], b[5], 0], (MAX_BOXES + i) * 4);
    }
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.boxTex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA32F, MAX_BOXES, 2, 0, gl.RGBA, gl.FLOAT, data);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);

    this.lightPos.fill(0);
    this.lightCol.fill(0);
    const nl = Math.min(map.LIGHTS.length, NUM_LIGHTS);
    for (let i = 0; i < nl; i++) {
      const L = map.LIGHTS[i];
      this.lightPos.set([L[0], L[1], L[2], L[6]], i * 4);
      this.lightCol.set([L[3], L[4], L[5]], i * 3);
    }
    this.muzzleIndex = nl - 1; // maps reserve their last light slot for muzzle flash

    const sl = Math.hypot(...map.SUN_DIR);
    this.sunDir = map.SUN_DIR.map(v => v / sl);
    this.sunCol = map.SUN_COLOR;
    this.sunInt = map.SUN_INTENSITY;
    this.theme = map.THEME;
  }

  // spheres: array of {x,y,z,r,mat,tint:[r,g,b]}
  setSpheres(list) {
    this.numSpheres = Math.min(list.length, MAX_SPHERES);
    for (let i = 0; i < this.numSpheres; i++) {
      const s = list[i];
      this.sphereData.set([s.x, s.y, s.z, s.r], i * 4);
      const t = s.tint || [1, 1, 1];
      this.sphereMats.set([s.mat, t[0], t[1], t[2]], i * 4);
    }
  }

  setMuzzleLight(x, y, z, intensity, col) {
    const i = this.muzzleIndex;
    if (i < 0) return;
    this.lightPos.set([x, y, z, intensity], i * 4);
    if (col) this.lightCol.set(col, i * 3);
  }

  resize(scale) {
    const c = this.canvas;
    const w = Math.max(2, Math.round(c.clientWidth * scale));
    const h = Math.max(2, Math.round(c.clientHeight * scale));
    if (c.width !== w || c.height !== h) {
      c.width = w;
      c.height = h;
    }
  }

  render(cam, time, gfx) {
    if (!this.theme) return; // no map loaded yet
    const gl = this.gl;
    const c = this.canvas;
    gl.viewport(0, 0, c.width, c.height);
    gl.useProgram(this.program);
    gl.bindVertexArray(this.vao);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.boxTex);
    gl.uniform1i(this.uni.uBoxTex, 0);
    gl.uniform1i(this.uni.uNumBoxes, this.numBoxes);

    gl.uniform2f(this.uni.uRes, c.width, c.height);
    gl.uniform1f(this.uni.uTime, time);
    gl.uniform3f(this.uni.uCamPos, cam.pos[0], cam.pos[1], cam.pos[2]);
    gl.uniform3f(this.uni.uCamFwd, cam.fwd[0], cam.fwd[1], cam.fwd[2]);
    gl.uniform3f(this.uni.uCamRight, cam.right[0], cam.right[1], cam.right[2]);
    gl.uniform3f(this.uni.uCamUp, cam.up[0], cam.up[1], cam.up[2]);
    gl.uniform1f(this.uni.uTanY, Math.tan(cam.fov * 0.5));

    gl.uniform4fv(this.uni.uSpheres, this.sphereData);
    gl.uniform4fv(this.uni.uSphereMat, this.sphereMats);
    gl.uniform1i(this.uni.uNumSpheres, this.numSpheres);

    gl.uniform3fv(this.uni.uSunDir, this.sunDir);
    gl.uniform3fv(this.uni.uSunCol, this.sunCol);
    gl.uniform1f(this.uni.uSunInt, this.sunInt);
    gl.uniform4fv(this.uni.uLightPos, this.lightPos);
    gl.uniform3fv(this.uni.uLightCol, this.lightCol);

    const T = this.theme;
    gl.uniform3fv(this.uni.uSkyTop, T.skyTop);
    gl.uniform3fv(this.uni.uSkyHorizon, T.skyHorizon);
    gl.uniform3fv(this.uni.uHaze, T.haze);
    gl.uniform3fv(this.uni.uFogCol, T.fogColor);
    gl.uniform3fv(this.uni.uNeonA, T.neonA);
    gl.uniform3fv(this.uni.uNeonB, T.neonB);

    gl.uniform1i(this.uni.uBounces, gfx.rayBounces);
    gl.uniform1i(this.uni.uShadowMode, gfx.shadowMode);
    gl.uniform1i(this.uni.uShadowSamples, gfx.softShadowSamples);
    gl.uniform1i(this.uni.uAOMode, gfx.aoMode);
    gl.uniform1i(this.uni.uFog, gfx.fog ? 1 : 0);
    gl.uniform1i(this.uni.uPulse, gfx.emissivePulse ? 1 : 0);
    gl.uniform1i(this.uni.uDebugMat, this.debugMat);

    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }
}
